<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, ArrowDownToLine, CheckCircle2, ChevronRight, CircleX, Clipboard, Clock3, FileClock, Fingerprint, RefreshCw, Search, ShieldCheck, ShieldX, UserRound } from 'lucide-vue-next'
import PageHeader from '../components/common/PageHeader.vue'
import StatePanel from '../components/common/StatePanel.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import AppModal from '../components/common/AppModal.vue'
import { api } from '../api'
import { asApiError, type ApiError } from '../api/errors'
import type { AuditEvent } from '../types/api'
import { useUiStore } from '../stores/ui'
import { useOnline } from '../composables/useOnline'
import { formatTime, relativeTime } from '../utils/format'
const ui=useUiStore(),{online}=useOnline()
const events=ref<AuditEvent[]>([]),loading=ref(true),error=ref<ApiError|null>(null),search=ref(''),result=ref('all'),action=ref('all'),selected=ref<AuditEvent>()
const filtered=computed(()=>events.value.filter(e=>(result.value==='all'||e.result===result.value)&&(action.value==='all'||e.action.startsWith(action.value))&&`${e.actor}${e.action}${e.target}${e.request_id}`.toLowerCase().includes(search.value.toLowerCase())))
const denied=computed(()=>events.value.filter(e=>e.result==='denied').length)
const commandCount=computed(()=>events.value.filter(e=>e.action.startsWith('command')).length)
async function load(){loading.value=true;error.value=null;try{events.value=await api.listAuditEvents()}catch(cause){error.value=asApiError(cause)}finally{loading.value=false}}
function exportCsv(){const rows=['event_id,time,actor,action,target,result,request_id,ip,detail',...filtered.value.map(e=>[e.id,new Date(e.occurred_at_ms).toISOString(),e.actor,e.action,e.target,e.result,e.request_id,e.ip||'',`"${e.detail||''}"`].join(','))];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='aurora-audit.csv';a.click();URL.revokeObjectURL(url)}
async function copyRequest(id:string){try{await navigator.clipboard.writeText(id);ui.toast('请求 ID 已复制','success')}catch{ui.toast('复制失败','error',id)}}
onMounted(()=>void load())
</script>
<template>
  <div class="page audit-page">
    <PageHeader eyebrow="AUDIT & COMPLIANCE" title="审计日志" subtitle="追溯身份、权限与关键运营操作；请求 ID 可关联服务端结构化日志。"><template #actions><button class="btn btn-secondary" @click="exportCsv"><ArrowDownToLine/>导出审计记录</button><button class="btn btn-primary" @click="load"><RefreshCw/>刷新</button></template></PageHeader>
    <div class="audit-summary"><article class="card"><span class="audit-summary-icon"><FileClock/></span><div><span>已载入事件</span><strong>{{ events.length }}</strong></div><small>当前查询范围</small></article><article class="card"><span class="audit-summary-icon denied"><ShieldX/></span><div><span>权限拒绝</span><strong>{{ denied }}</strong></div><small>服务端强制拦截</small></article><article class="card"><span class="audit-summary-icon command"><Activity/></span><div><span>控车操作</span><strong>{{ commandCount }}</strong></div><small>完整链路追踪</small></article><div class="integrity"><Fingerprint/><div><strong>审计完整性保护</strong><span>事件只追加 · 时间戳 UTC · 请求级关联</span></div><ShieldCheck/></div></div>
    <StatePanel :loading="loading" :error="error" :offline="!online&&!events.length" @retry="load">
      <section class="card audit-card"><div class="audit-filters"><div class="search-field"><Search/><input v-model="search" class="input" placeholder="搜索操作人、对象或请求 ID"></div><select v-model="action" class="select"><option value="all">全部事件类型</option><option value="auth">身份认证</option><option value="command">车辆指令</option><option value="alert">告警处理</option><option value="device">设备管理</option><option value="vehicle">车辆权限</option></select><select v-model="result" class="select"><option value="all">全部结果</option><option value="success">成功</option><option value="denied">已拒绝</option><option value="failed">失败</option></select><button class="btn btn-secondary"><Clock3/>最近 24 小时</button></div>
        <div class="table-wrap"><table><thead><tr><th>发生时间</th><th>操作人</th><th>事件</th><th>目标对象</th><th>结果</th><th>请求 ID</th><th>来源 IP</th><th/></tr></thead><tbody><tr v-for="event in filtered" :key="event.id"><td><div class="event-time"><strong>{{ formatTime(event.occurred_at_ms) }}</strong><small>{{ formatTime(event.occurred_at_ms,true).split(' ')[0] }} · {{ relativeTime(event.occurred_at_ms) }}</small></div></td><td><span class="actor"><UserRound/>{{ event.actor }}</span></td><td><span class="action-tag mono">{{ event.action }}</span></td><td><strong class="target mono">{{ event.target }}</strong></td><td><StatusBadge :status="event.result" :label="event.result==='success'?'成功':event.result==='denied'?'已拒绝':'失败'"/></td><td><button class="request-link mono" @click="copyRequest(event.request_id)">{{ event.request_id }}<Clipboard/></button></td><td class="mono">{{ event.ip||'internal' }}</td><td><button class="btn btn-ghost btn-icon btn-sm" @click="selected=event"><ChevronRight/></button></td></tr></tbody></table></div><StatePanel :empty="!filtered.length" compact title="没有匹配的审计事件" description="调整事件类型、结果或搜索条件后重试。"/><div class="audit-footer"><span><ShieldCheck/>审计数据来自服务端，前端不提供编辑或删除能力。</span><span>显示 {{ filtered.length }} / {{ events.length }} 条</span></div>
      </section>
    </StatePanel>
    <AppModal :open="!!selected" title="审计事件详情" eyebrow="EVENT INSPECTION" @close="selected=undefined"><template v-if="selected"><div class="event-result" :class="selected.result"><CheckCircle2 v-if="selected.result==='success'"/><ShieldX v-else-if="selected.result==='denied'"/><CircleX v-else/><div><strong>{{ selected.action }}</strong><span>{{ selected.result==='success'?'操作已成功执行':selected.result==='denied'?'服务端权限策略已拒绝':'操作执行失败' }}</span></div></div><dl class="event-detail"><div><dt>事件 ID</dt><dd class="mono">{{ selected.id }}</dd></div><div><dt>请求 ID</dt><dd class="mono">{{ selected.request_id }}</dd></div><div><dt>操作人</dt><dd>{{ selected.actor }}</dd></div><div><dt>目标对象</dt><dd class="mono">{{ selected.target }}</dd></div><div><dt>发生时间</dt><dd>{{ new Date(selected.occurred_at_ms).toISOString() }}</dd></div><div><dt>来源地址</dt><dd class="mono">{{ selected.ip||'internal' }}</dd></div><div><dt>事件说明</dt><dd>{{ selected.detail||'—' }}</dd></div></dl></template><template #footer><button class="btn btn-secondary" @click="selected=undefined">关闭</button><button class="btn btn-primary" @click="selected&&copyRequest(selected.request_id)"><Clipboard/>复制请求 ID</button></template></AppModal>
  </div>
</template>
<style scoped>
.audit-summary{display:grid;grid-template-columns:repeat(3,minmax(150px,.65fr)) minmax(280px,1.4fr);gap:18px;margin-bottom:18px}.audit-summary>article{padding:17px 18px;display:flex;align-items:center;gap:12px}.audit-summary-icon{width:36px;height:36px;border-radius:10px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center}.audit-summary-icon.denied{background:var(--red-soft);color:var(--red)}.audit-summary-icon.command{background:var(--cyan-soft);color:var(--cyan)}.audit-summary-icon svg{width:17px}.audit-summary article>div{display:flex;flex-direction:column;gap:4px}.audit-summary article span{font-size:8px;color:var(--muted)}.audit-summary article strong{font-size:20px}.audit-summary article>small{margin-left:auto;font-size:7px;color:var(--muted)}.integrity{border:1px solid color-mix(in srgb,var(--green) 20%,var(--line));border-radius:var(--radius);background:var(--green-soft);display:flex;align-items:center;padding:15px 18px;gap:12px;color:var(--green)}.integrity>svg{width:20px}.integrity>svg:last-child{width:16px;margin-left:auto}.integrity>div{display:flex;flex-direction:column;gap:5px}.integrity strong{font-size:10px}.integrity span{font-size:8px;opacity:.75}.audit-filters{display:flex;gap:10px;padding:16px 18px;border-bottom:1px solid var(--line)}.audit-filters .search-field{flex:1}.audit-filters .select{width:140px}.event-time{display:flex;flex-direction:column;gap:4px}.event-time strong{font-size:10px}.event-time small{font-size:8px;color:var(--muted)}.actor{display:flex;align-items:center;gap:6px}.actor svg{width:13px;color:var(--muted)}.action-tag{font-size:9px;color:var(--primary);background:var(--primary-soft);padding:4px 6px;border-radius:5px}.target{font-size:9px}.request-link{display:flex;align-items:center;gap:5px;border:0;background:transparent;color:var(--text-2);font-size:8px;cursor:pointer}.request-link:hover{color:var(--primary)}.request-link svg{width:10px}.audit-footer{padding:12px 18px;background:var(--bg-soft);border-top:1px solid var(--line);display:flex;justify-content:space-between;font-size:8px;color:var(--muted)}.audit-footer span:first-child{display:flex;align-items:center;gap:6px}.audit-footer svg{width:12px;color:var(--green)}.event-result{display:flex;align-items:center;gap:11px;background:var(--green-soft);color:var(--green);padding:13px;border-radius:10px;margin-bottom:16px}.event-result.denied{background:var(--orange-soft);color:var(--orange)}.event-result.failed{background:var(--red-soft);color:var(--red)}.event-result>svg{width:20px}.event-result>div{display:flex;flex-direction:column;gap:4px}.event-result strong{font-size:11px}.event-result span{font-size:9px}.event-detail{margin:0}.event-detail>div{display:grid;grid-template-columns:95px 1fr;gap:15px;padding:10px 0;border-bottom:1px solid var(--line);font-size:10px}.event-detail dt{color:var(--muted)}.event-detail dd{margin:0;color:var(--text);word-break:break-all}
@media(max-width:1200px){.audit-summary{grid-template-columns:repeat(3,1fr)}.integrity{grid-column:1/-1}.audit-filters{flex-wrap:wrap}.audit-filters .search-field{min-width:100%}}
</style>
